/// `model.ModeratedBookmarkPermissions` — the eight channel-bookmark permissions that channel moderation collapses into the
/// single `manage_bookmarks` control.
#[rustfmt::skip]
pub static MODERATED_BOOKMARK_PERMISSIONS: &[&Permission] = &[
    &PERMISSION_ADD_BOOKMARK_PUBLIC_CHANNEL,
    &PERMISSION_EDIT_BOOKMARK_PUBLIC_CHANNEL,
    &PERMISSION_DELETE_BOOKMARK_PUBLIC_CHANNEL,
    &PERMISSION_ORDER_BOOKMARK_PUBLIC_CHANNEL,
    &PERMISSION_ADD_BOOKMARK_PRIVATE_CHANNEL,
    &PERMISSION_EDIT_BOOKMARK_PRIVATE_CHANNEL,
    &PERMISSION_DELETE_BOOKMARK_PRIVATE_CHANNEL,
    &PERMISSION_ORDER_BOOKMARK_PRIVATE_CHANNEL,
];

/// `model.ChannelModeratedPermissions` — the five controls the channel-moderation UI
/// offers, in Go's order. These are **not** permission ids: `create_reactions`,
/// `manage_members` and `manage_bookmarks` name no permission and exist only here.
#[rustfmt::skip]
pub static CHANNEL_MODERATED_PERMISSIONS: &[&str] = &[
    "create_post",
    "create_reactions",
    "manage_members",
    "use_channel_mentions",
    "manage_bookmarks",
];

/// `model.ChannelModeratedPermissionsMap` — which moderation control a permission id
/// belongs to. Sorted by key so [`slice::binary_search_by_key`] applies. Go's map has no
/// order; its one ranging caller (`role.go:713`) uses the loop to find a key it already
/// holds and writes into a map, so no result depends on the order.
#[rustfmt::skip]
pub static CHANNEL_MODERATED_PERMISSIONS_MAP: &[(&str, &str)] = &[
    ("add_bookmark_private_channel", "manage_bookmarks"),
    ("add_bookmark_public_channel", "manage_bookmarks"),
    ("add_reaction", "create_reactions"),
    ("create_post", "create_post"),
    ("delete_bookmark_private_channel", "manage_bookmarks"),
    ("delete_bookmark_public_channel", "manage_bookmarks"),
    ("edit_bookmark_private_channel", "manage_bookmarks"),
    ("edit_bookmark_public_channel", "manage_bookmarks"),
    ("manage_private_channel_members", "manage_members"),
    ("manage_public_channel_members", "manage_members"),
    ("order_bookmark_private_channel", "manage_bookmarks"),
    ("order_bookmark_public_channel", "manage_bookmarks"),
    ("remove_reaction", "create_reactions"),
    ("use_channel_mentions", "use_channel_mentions"),
];
